<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, Link, router } from '@inertiajs/vue3'; defineProps<{students:any[]}>(); const archive=(s:any)=>confirm(`Archive ${s.preferred_name || s.first_name}? Enrollment history will remain available.`)&&router.patch(route('students.archive',s.id));</script>
<template><Head title="Students"/><AuthenticatedLayout><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Students</h1><p class="text-secondary mb-0">Academic profiles are separate from login accounts.</p></div><Link class="btn btn-primary" :href="route('students.create')">Add student</Link></div><div class="card"><div v-if="!students.length" class="empty-state"><h2 class="h5">No students yet</h2><p>Add a student without needing an email address or login.</p></div><div v-else class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Name</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-for="s in students" :key="s.id"><td><Link :href="route('students.show',s.id)">{{ s.preferred_name || s.first_name }} {{ s.last_name }}</Link></td><td><span class="badge status-badge" :class="s.status==='active'?'text-bg-success':'text-bg-secondary'">{{ s.status }}</span></td><td class="text-end"><Link class="btn btn-sm btn-outline-secondary me-2" :href="route('students.edit',s.id)">Edit</Link><button v-if="s.status!=='archived'" class="btn btn-sm btn-outline-danger" @click="archive(s)">Archive</button></td></tr></tbody></table></div></div></AuthenticatedLayout></template>
